insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('aaaa0005-0000-4000-8000-000000000006', 'en', 'us', 'Business English for the Workplace', 'A CEFR B2-level English-for-specific-purposes course for working professionals. Build the vocabulary, grammar, and communication skills you need to network, run meetings, write clear emails, negotiate, and handle feedback in an American workplace.', 'B2', 'work', 14, true, 'language', '{aaaa0005-0000-4000-8000-000000000003}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'aaaa0005-0000-4000-8000-000000000006', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Introductions and networking', 'vocab', '{"items":[{"term":"What do you do?","translation":"a standard question asking about someone''s job or profession","ipa":"ˈwʌt du ju ˈdu","example":"So, what do you do? — I''m a project manager at a software company."},{"term":"I''m in charge of…","translation":"a phrase for describing what you are responsible for at work","ipa":"aɪm ɪn ˈtʃɑrdʒ ʌv","example":"I''m in charge of onboarding new clients in the northeast region."},{"term":"We actually met at…","translation":"a friendly way to remind someone where you met before","ipa":"wi ˈæktʃuəli ˈmɛt æt","example":"We actually met at last year''s conference in Austin."},{"term":"reach out","translation":"to contact someone, usually to start a professional conversation","ipa":"ˈritʃ ˈaʊt","example":"Feel free to reach out if you ever want to compare notes."},{"term":"touch base","translation":"to have a short conversation to share updates or reconnect","ipa":"ˈtʌtʃ ˈbeɪs","example":"Let''s touch base early next week to see where things stand."},{"term":"Here''s my card","translation":"what you say when handing someone your business card","ipa":"hɪrz maɪ ˈkɑrd","example":"Here''s my card — my direct line is on the back."}]}'::jsonb, 'At networking events, follow your name with a short role summary using *I* + present simple: *I lead the design team.* Then hand the conversation back with a question — Americans expect a quick back-and-forth, not a monologue.', 9),
  (2, 'Diplomatic language and hedging', 'grammar', '{"sections":[{"heading":"Why professionals soften their language","text":"In a B2 workplace, being direct can sound blunt or even aggressive. English speakers use hedging — small softening words and structures — to sound collaborative and to leave room for other opinions. Compare the blunt *This plan is wrong* with the diplomatic *I''m not sure this plan is quite right yet.* Both give the same message, but the second keeps the relationship intact and invites discussion."},{"heading":"Hedging toolkit","text":"Reach for these when you disagree, deliver bad news, or make a request. Softeners: *a bit, slightly, kind of, a little.* Cautious verbs: *seem, appear, tend to* — as in *This tends to slow us down.* Modal verbs: *might, could, may* — *We could look at another option.* Openers: *I''m afraid…, To be honest…, It might be worth…* — as in *I''m afraid we''re a little behind schedule.*"},{"heading":"Questions and qualifiers","text":"Turning a statement into a question makes it gentler: instead of *Do it by Friday*, try *Would it be possible to have it by Friday?* Qualifiers like *I think, I feel, in my view*, and *from what I can see* signal that you are offering an opinion, not a verdict. Adding *just* also lowers the pressure: *I just wanted to check in on the numbers.*"},{"heading":"Don''t over-hedge","text":"Softening is about respect, not vagueness. If every sentence is buried under *maybe, sort of, possibly*, your message gets lost and you can sound unsure of yourself. The B2 skill is balance: hedge the delivery, but keep the point clear. *I think we may want to revisit the budget* still tells everyone exactly what you mean."}]}'::jsonb, null, 12),
  (3, 'Working the room', 'roleplay', '{"scenario":"An industry networking mixer after a conference. You are holding a drink and standing near someone you have never met. Introduce yourself, explain what you do in one or two sentences, find something you have in common, and exchange contact details before moving on to the next person.","persona":"A friendly but busy sales director who meets dozens of people at these events and appreciates people who get to the point","goal":"Introduce yourself clearly, ask at least two follow-up questions, discover one shared interest, and agree to connect afterward"}'::jsonb, null, 12),
  (4, 'Meetings and presentations', 'vocab', '{"items":[{"term":"get the ball rolling","translation":"to start an activity or a meeting","ipa":"ˈɡɛt ðə ˈbɔl ˈroʊlɪŋ","example":"Let''s get the ball rolling — Priya, can you walk us through the numbers?"},{"term":"on the same page","translation":"in agreement, sharing the same understanding","ipa":"ɑn ðə ˈseɪm ˈpeɪdʒ","example":"Before we go further, I want to make sure we''re all on the same page."},{"term":"circle back","translation":"to return to a topic later in the discussion","ipa":"ˈsɜrkəl ˈbæk","example":"That''s a great point — can we circle back to it after the demo?"},{"term":"action item","translation":"a specific task someone must do after the meeting","ipa":"ˈækʃən ˈaɪtəm","example":"The main action item is to send the revised proposal by Thursday."},{"term":"take it offline","translation":"to discuss something privately, outside the current meeting","ipa":"ˈteɪk ɪt ˈɔflaɪn","example":"This is getting detailed — why don''t we take it offline?"},{"term":"any questions?","translation":"a phrase inviting the audience to ask about your presentation","ipa":"ˈɛni ˈkwɛstʃənz","example":"That covers the roadmap. Any questions before we move on?"}]}'::jsonb, 'Use signposting phrases to guide listeners through a presentation: *First, I''ll…, Moving on to…, To wrap up…* These transitions are fixed chunks — learn them as whole phrases rather than word by word.', 9),
  (5, 'Running the weekly meeting', 'roleplay', '{"scenario":"You are leading your team''s weekly status meeting over video. Open the meeting, keep it moving through three agenda items, manage a colleague who keeps going off topic, and close by assigning clear action items with owners and deadlines.","persona":"A talkative teammate who has strong opinions and tends to dominate the discussion unless gently redirected","goal":"Open and structure the meeting, politely keep it on track, and finish with at least two assigned action items"}'::jsonb, null, 13),
  (6, 'The language of negotiation', 'vocab', '{"items":[{"term":"meet in the middle","translation":"to reach a compromise where each side gives up something","ipa":"ˈmit ɪn ðə ˈmɪdəl","example":"You want twelve, we said eight — can we meet in the middle at ten?"},{"term":"deal breaker","translation":"a condition that will stop an agreement if it is not met","ipa":"ˈdil ˌbreɪkər","example":"A flexible payment schedule isn''t a deal breaker, but it would help."},{"term":"wiggle room","translation":"flexibility to change the terms of an offer","ipa":"ˈwɪɡəl ˌrum","example":"Honestly, we don''t have much wiggle room on the timeline."},{"term":"bottom line","translation":"the lowest terms someone is willing to accept","ipa":"ˈbɑtəm ˈlaɪn","example":"My bottom line is that delivery has to happen before the holidays."},{"term":"throw in","translation":"to add something extra to an offer at no additional cost","ipa":"ˈθroʊ ˈɪn","example":"If you commit today, we can throw in a year of support."},{"term":"sleep on it","translation":"to take time before deciding, usually overnight","ipa":"ˈslip ɑn ɪt","example":"It''s a big commitment, so I''d like to sleep on it and reply tomorrow."}]}'::jsonb, 'Negotiators lean on conditionals to make offers without committing: *If you can move on price, we could sign this week.* Notice the *if* clause sets the condition and the result clause stays tentative with *could* or *would*.', 9),
  (7, 'Conditionals for negotiation', 'grammar', '{"sections":[{"heading":"The first conditional: real offers","text":"Use the first conditional for offers you can actually deliver: *if* + present simple, then *will/can*. For example, *If you sign by Friday, we''ll waive the setup fee.* This structure links a concrete condition to a concrete result, which is exactly what a negotiation trades in. It signals confidence — you mean what you say."},{"heading":"The second conditional: testing the water","text":"When you want to explore a possibility without committing, switch to the second conditional: *if* + past simple, then *would/could/might*. *If we increased the order, would you lower the unit price?* The past tense here does not mean past time — it makes the offer feel hypothetical and safer, so nobody loses face if the answer is no."},{"heading":"Choosing between them","text":"First conditional sounds firm and likely; second conditional sounds tentative and exploratory. Skilled negotiators move between the two on purpose. Open with the second to float ideas — *Suppose we split the shipping, how would that sit with you?* — then move to the first once you''re close: *If you can cover shipping, we''ll start on Monday.*"},{"heading":"Common slips to avoid","text":"Don''t mix *will* into the *if* clause: say *If you agree* (not *If you will agree*). Keep contractions natural in speech: *we''ll, you''d, it''d.* And remember that *unless* means *if not* — *We can''t proceed unless the terms change* equals *…if the terms don''t change.* Small errors here can change your offer, so read conditions back to confirm."}]}'::jsonb, null, 13),
  (8, 'A feedback conversation on video', 'roleplay', '{"scenario":"A one-on-one video call with a team member whose recent report missed the mark. Open warmly, give specific, constructive feedback using diplomatic language, listen to their side, and agree together on two concrete next steps. Then handle a moment where they respond a little defensively.","persona":"A capable but sensitive colleague who worked hard on the report and feels a bit defensive when it is criticized","goal":"Deliver honest feedback kindly, acknowledge the colleague''s effort and viewpoint, and end with a shared plan and a positive tone"}'::jsonb, null, 13),
  (9, 'Emails, follow-ups, and meeting summaries', 'writing', '{"sections":[{"heading":"Structure and subject lines","text":"A clear professional email opens with a subject line that names the topic and any action: *Action needed: sign-off on Q3 budget by Fri.* Keep the body to a short greeting, one main point per paragraph, and a specific request or next step at the end. Busy readers skim, so put the most important sentence first rather than saving it for the close."},{"heading":"Setting the right tone","text":"Match your formality to the reader. With a new contact, use *Dear Ms. Alvarez* and full sentences; with a familiar teammate, *Hi Sam* is fine. Requests stay polite with *Could you…, Would you mind…,* and *When you get a chance…* Close with a warm, standard sign-off such as *Best regards* or *Thanks so much* — and always say clearly what you need and by when."},{"heading":"Writing a meeting summary with reported speech","text":"A follow-up email that summarizes a meeting usually shifts into reported speech, moving the verb one step back in time. *\"I''ll send the file\"* becomes *Dana said she would send the file.* *\"We can start Monday\"* becomes *The vendor said they could start Monday.* Pronouns and time words shift too: *tomorrow* becomes *the next day.* Use reporting verbs that capture intent — *agreed, confirmed, suggested, raised a concern* — so the record is both accurate and easy to scan."},{"heading":"Polishing and following up","text":"Before sending, reread once for tone and twice for typos, and confirm every name, date, and figure. If you need a reply and haven''t heard back, a short, friendly nudge after a few days is normal and expected: *Just following up on my note below — any thoughts when you have a moment?* Keep follow-ups light and never accusing; assume the reader is simply busy."}]}'::jsonb, null, 12),
  (10, 'Checkpoint', 'quiz', '{"questions":[{"prompt":"A colleague says, \"Let''s touch base next week.\" This means they want to…","options":["end the project","have a short conversation to reconnect and share updates","criticize your work","cancel the meeting"],"answer":1,"explanation":"*Touch base* means to briefly reconnect and exchange updates, not to make a final decision."},{"prompt":"Which sentence hedges the message most diplomatically?","options":["This idea is bad.","You''re wrong about this.","I''m not sure this is quite the right approach yet.","Do it my way."],"answer":2,"explanation":"Softeners like *not sure*, *quite*, and *yet* deliver the same concern while keeping the tone collaborative."},{"prompt":"Complete the first conditional offer: \"If you sign by Friday, we ___ the setup fee.\"","options":["waived","will waive","would have waived","waiving"],"answer":1,"explanation":"The first conditional uses *if* + present simple, then *will* + base verb for a real, deliverable offer."},{"prompt":"You want to float an idea without committing. Which structure fits best?","options":["If you increase the order, we lowered the price.","If you increased the order, would you get a lower price?","If you will increase the order, we lower the price.","If you increase the order, we lowering the price."],"answer":1,"explanation":"The second conditional (*if* + past simple, then *would*) makes an offer feel hypothetical and safe to explore."},{"prompt":"In a meeting summary email, \"I''ll send the report tomorrow\" becomes:","options":["He says he will send the report tomorrow.","He said he would send the report the next day.","He said he will send the report tomorrow.","He said he sends the report the next day."],"answer":1,"explanation":"Reported speech shifts *will* to *would* and *tomorrow* to *the next day* to match the reporting time."},{"prompt":"Which phrase most politely redirects an off-topic point in a meeting?","options":["That''s irrelevant.","Stop talking about that.","That''s a good point — can we circle back to it later?","We don''t have time for you."],"answer":2,"explanation":"Acknowledging the point and offering to *circle back* keeps the meeting on track without dismissing the person."}]}'::jsonb, null, 8)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'aaaa0005-0000-4000-8000-000000000006' and l.position = v.pos
);
